async function writeSection(state, key, content) {
  const existing = await state.idempotency.get(key)
  if (existing) return { ok: true, duplicate: true, revision: existing.revision }
  const revision = await state.machine.expectRevision(state.project, state.expectedRevision)
  await state.storage.commit({ key, content, revision })
  return { ok: true, duplicate: false, revision }
}
